#!/usr/bin/env python3
"""
Regenerate the .po catalogues from the strings actually present in the source.

Rationale: the catalogues had drifted badly (82 strings missing, 32 stale) because
they were maintained by hand. This script derives the msgid list from the code via
extract_strings.py and pairs it with the Russian map below, so the catalogues
cannot silently fall out of step again.

Usage:
    python3 update_translations.py        # rewrite locale/{en,ru}/.../*.po
    python3 update_translations.py --check # report drift, write nothing
    python3 compile_translations.py       # then build the .mo files

Any msgid without an entry in RU is written with an empty msgstr, which makes
gettext fall back to the English text rather than showing nothing.
"""
import sys
from datetime import datetime
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from extract_strings import extract_source_strings, parse_po, po_escape

